/// <summary>
/// A <see cref="ContentBlock"/> variant this protocol version does not define.
/// </summary>
/// <remarks>
/// Holds the payload verbatim so it can be stored, replayed, or proxied unchanged.
/// ACP v2 requires that; failing to parse instead would lose the whole message.
/// </remarks>
public sealed class ContentBlockUnknown : ContentBlock
{
    /// <inheritdoc/>
    [JsonIgnore]
    public override string Discriminator => Kind;
    /// <summary>The discriminator value that was received.</summary>
    public required string Kind { get; init; }
    /// <summary>The payload exactly as it arrived.</summary>
    public required JsonElement Raw { get; init; }
}

/// <summary>Resolves <see cref="ContentBlock"/> by its <c>type</c> discriminator.</summary>
internal sealed class ContentBlockConverter : JsonConverter<ContentBlock>
{
    /// <inheritdoc/>
    public override ContentBlock Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        using var document = JsonDocument.ParseValue(ref reader);
        var root = document.RootElement;
        var kind = root.TryGetProperty("type", out var marker) && marker.ValueKind == JsonValueKind.String ? marker.GetString() : null;
        return kind switch
        {
            "text" => new ContentBlockText
            {
                Value = AcpJson.Read<TextContent>(root, options)
            },
            "image" => new ContentBlockImage
            {
                Value = AcpJson.Read<ImageContent>(root, options)
            },
            "audio" => new ContentBlockAudio
            {
                Value = AcpJson.Read<AudioContent>(root, options)
            },
            "resource_link" => new ContentBlockResourceLink
            {
                Value = AcpJson.Read<ResourceLink>(root, options)
            },
            "resource" => new ContentBlockResource
            {
                Value = AcpJson.Read<EmbeddedResource>(root, options)
            },
            _ => new ContentBlockUnknown
            {
                Kind = kind ?? string.Empty,
                Raw = root.Clone()
            },
        };
    }

    /// <inheritdoc/>
    public override void Write(Utf8JsonWriter writer, ContentBlock value, JsonSerializerOptions options)
    {
        if (value is ContentBlockUnknown unknown)
        {
            unknown.Raw.WriteTo(writer);
            return;
        }

        writer.WriteStartObject();
        writer.WriteString("type", value.Discriminator);
        switch (value)
        {
            case ContentBlockText typed:
            AcpJson.WriteMembers(writer, typed.Value, options);
            break;
            case ContentBlockImage typed:
            AcpJson.WriteMembers(writer, typed.Value, options);
            break;
            case ContentBlockAudio typed:
            AcpJson.WriteMembers(writer, typed.Value, options);
            break;
            case ContentBlockResourceLink typed:
            AcpJson.WriteMembers(writer, typed.Value, options);
            break;
            case ContentBlockResource typed:
            AcpJson.WriteMembers(writer, typed.Value, options);
            break;
            default:
            break;
        }

        writer.WriteEndObject();
    }
}

