/// Holds the payload verbatim so it can be stored, replayed, or proxied unchanged.
/// ACP v2 requires that; failing to parse instead would lose the whole message.
/// </remarks>
public sealed class ElicitationPropertySchemaUnknown : ElicitationPropertySchema
{
    /// <inheritdoc/>
    [JsonIgnore]
    public override string Discriminator => Kind;
    /// <summary>The discriminator value that was received.</summary>
    public required string Kind { get; init; }
    /// <summary>The payload exactly as it arrived.</summary>
    public required JsonElement Raw { get; init; }
}

/// <summary>Resolves <see cref="ElicitationPropertySchema"/> by its <c>type</c> discriminator.</summary>
internal sealed class ElicitationPropertySchemaConverter : JsonConverter<ElicitationPropertySchema>
{
    /// <inheritdoc/>
    public override ElicitationPropertySchema Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        using var document = JsonDocument.ParseValue(ref reader);
        var root = document.RootElement;
        var kind = root.TryGetProperty("type", out var marker) && marker.ValueKind == JsonValueKind.String ? marker.GetString() : null;
        return kind switch
        {
            "string" => new ElicitationPropertySchemaString
            {
                Value = AcpJson.Read<StringPropertySchema>(root, options)
            },
            "number" => new ElicitationPropertySchemaNumber
            {
                Value = AcpJson.Read<NumberPropertySchema>(root, options)
            },
            "integer" => new ElicitationPropertySchemaInteger
            {
                Value = AcpJson.Read<IntegerPropertySchema>(root, options)
            },
            "boolean" => new ElicitationPropertySchemaBoolean
            {
                Value = AcpJson.Read<BooleanPropertySchema>(root, options)
            },
            "array" => new ElicitationPropertySchemaArray
            {
                Value = AcpJson.Read<MultiSelectPropertySchema>(root, options)
            },
            _ => new ElicitationPropertySchemaUnknown
            {
                Kind = kind ?? string.Empty,
                Raw = root.Clone()
            },
        };
    }

    /// <inheritdoc/>
    public override void Write(Utf8JsonWriter writer, ElicitationPropertySchema value, JsonSerializerOptions options)
    {
        if (value is ElicitationPropertySchemaUnknown unknown)
        {
            unknown.Raw.WriteTo(writer);
            return;
        }

        writer.WriteStartObject();
        writer.WriteString("type", value.Discriminator);
        switch (value)
        {
            case ElicitationPropertySchemaString typed:
            AcpJson.WriteMembers(writer, typed.Value, options);
            break;
            case ElicitationPropertySchemaNumber typed:
            AcpJson.WriteMembers(writer, typed.Value, options);
            break;
            case ElicitationPropertySchemaInteger typed:
            AcpJson.WriteMembers(writer, typed.Value, options);
            break;
            case ElicitationPropertySchemaBoolean typed:
            AcpJson.WriteMembers(writer, typed.Value, options);
            break;
            case ElicitationPropertySchemaArray typed:
            AcpJson.WriteMembers(writer, typed.Value, options);
            break;
            default:
            break;
        }

        writer.WriteEndObject();
    }
}

