/// <summary>
/// JSON RPC Request Id
///
/// An identifier established by the Client that MUST contain a String, Number, or NULL value if included. If it is not included it is assumed to be a notification. The value SHOULD normally not be Null \[1\] and Numbers SHOULD NOT contain fractional parts \[2\]
///
/// The Server MUST reply with the same value in the Response object if included. This member is used to correlate the context between the two objects.
///
/// \[1\] The use of Null as a value for the id member in a Request object is discouraged, because this specification uses a value of Null for Responses with an unknown id. Also, because JSON-RPC 1.0 uses an id value of Null for Notifications this could cause confusion in handling.
///
/// \[2\] Fractional parts may be problematic, since many decimal fractions cannot be represented exactly as binary fractions.
/// </summary>
[JsonConverter(typeof(RequestIdConverter))]
public readonly struct RequestId
{
    /// <summary>Wrap a raw payload.</summary>
    public RequestId(JsonElement raw) => Raw = raw;
    /// <summary>The value exactly as it arrived.</summary>
    public JsonElement Raw { get; }
    /// <summary>Whether the value is absent.</summary>
    public bool IsNull => Raw.ValueKind is JsonValueKind.Null or JsonValueKind.Undefined;

    /// <summary>Read this value as <c>long</c>, when that is what it holds.</summary>
    public bool TryGetLong(JsonSerializerOptions options, out long value) => AcpJson.TryRead(Raw, options, out value);
    /// <summary>Read this value as <c>long</c> using this protocol version's contracts.</summary>
    public bool TryGetLong(out long value) => AcpJson.TryRead(Raw, AcpUnstableJsonContext.Default.Options, out value);
    /// <summary>Read this value as <c>string</c>, when that is what it holds.</summary>
    public bool TryGetString(JsonSerializerOptions options, out string value) => AcpJson.TryRead(Raw, options, out value);
    /// <summary>Read this value as <c>string</c> using this protocol version's contracts.</summary>
    public bool TryGetString(out string value) => AcpJson.TryRead(Raw, AcpUnstableJsonContext.Default.Options, out value);
}

