/// <summary>
/// The prompt turn was cancelled before the user responded.
///
/// When a client sends a `session/cancel` notification to cancel an ongoing
/// prompt turn, it MUST respond to all pending `session/request_permission`
/// requests with this `Cancelled` outcome.
///
/// See protocol docs: [Cancellation](https://agentclientprotocol.com/protocol/prompt-turn#cancellation)
/// </summary>
public sealed class RequestPermissionOutcomeCancelled : RequestPermissionOutcome
{
    /// <inheritdoc/>
    [JsonIgnore]
    public override string Discriminator => "cancelled";
}

/// <summary>
/// The user selected one of the provided options.
/// </summary>
public sealed class RequestPermissionOutcomeSelected : RequestPermissionOutcome
{
    /// <inheritdoc/>
    [JsonIgnore]
    public override string Discriminator => "selected";
    /// <summary>The fields this variant carries, flattened alongside the discriminator on the wire.</summary>
    public required SelectedPermissionOutcome Value { get; init; }
}

/// <summary>
/// A <see cref="RequestPermissionOutcome"/> variant this protocol version does not define.
/// </summary>
/// <remarks>
/// Holds the payload verbatim so it can be stored, replayed, or proxied unchanged.
/// ACP v2 requires that; failing to parse instead would lose the whole message.
/// </remarks>
public sealed class RequestPermissionOutcomeUnknown : RequestPermissionOutcome
{
    /// <inheritdoc/>
    [JsonIgnore]
    public override string Discriminator => Kind;
    /// <summary>The discriminator value that was received.</summary>
    public required string Kind { get; init; }
    /// <summary>The payload exactly as it arrived.</summary>
    public required JsonElement Raw { get; init; }
}

/// <summary>Resolves <see cref="RequestPermissionOutcome"/> by its <c>outcome</c> discriminator.</summary>
internal sealed class RequestPermissionOutcomeConverter : JsonConverter<RequestPermissionOutcome>
{
    /// <inheritdoc/>
    public override RequestPermissionOutcome Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        using var document = JsonDocument.ParseValue(ref reader);
        var root = document.RootElement;
        var kind = root.TryGetProperty("outcome", out var marker) && marker.ValueKind == JsonValueKind.String ? marker.GetString() : null;
        return kind switch
        {
            "cancelled" => new RequestPermissionOutcomeCancelled
            {
            },
            "selected" => new RequestPermissionOutcomeSelected
            {
                Value = AcpJson.Read<SelectedPermissionOutcome>(root, options)
            },
            _ => new RequestPermissionOutcomeUnknown
            {
                Kind = kind ?? string.Empty,
                Raw = root.Clone()
            },
        };
    }

    /// <inheritdoc/>
    public override void Write(Utf8JsonWriter writer, RequestPermissionOutcome value, JsonSerializerOptions options)
    {
        if (value is RequestPermissionOutcomeUnknown unknown)
        {
            unknown.Raw.WriteTo(writer);
            return;
        }

        writer.WriteStartObject();
        writer.WriteString("outcome", value.Discriminator);
        switch (value)
        {
            case RequestPermissionOutcomeCancelled typed:
            break;
            case RequestPermissionOutcomeSelected typed:
            AcpJson.WriteMembers(writer, typed.Value, options);
            break;
            default:
            break;
        }

        writer.WriteEndObject();
    }
}

